ACTIONS = [json.loads(zlib.decompress(base64.b85decode(x)).decode()) for x in (_P0, _P1)]
SEAT_MODE = "AUTO"
CLAMP_SELL = True

def act(observation, configuration):
    player = int(observation.get("player", 0))
    schedule_side = player if SEAT_MODE == "AUTO" else int(SEAT_MODE[-1])
    step = min(int(observation.get("step", 0)), len(ACTIONS[schedule_side]) - 1)
    action = copy.deepcopy(ACTIONS[schedule_side][step])
    shed = (observation.get("private") or {}).get("shed") or {}
    market = []
    for order in action.get("market") or []:
        if CLAMP_SELL and order and order[0] == "SELL":
            qty = min(int(order[2]), int(shed.get(order[1], 0) or 0))
            if qty > 0:
                market.append(["SELL", order[1], qty])
        else:
            market.append(order)
    action["market"] = market
    # A missing hire can change the valid hand count; never emit excess ops.
    hands = (observation.get("farms") or [])[player].get("hands") or []
    action["hands"] = (action.get("hands") or [])[:len(hands)]
    return action

def agent(observation, configuration):
    return act(observation, configuration)
